def ways(n):
    if n == 0:
        return 1
    if n < 0:
        return 0
    return ways(n - 1) + ways(n - 2)

def subset_sum(a, k, i=0):
    if k == 0:
        return True
    if i == len(a):
        return False
    return subset_sum(a, k - a[i], i + 1) or subset_sum(a, k, i + 1)

print(ways(4), ways(10))
print(subset_sum([3, 7, 1, 8], 11), subset_sum([3, 7, 1, 8], 6))

